// ui_templates.h - screen templates generated by Flipper UI Studio (format 1). Put it in
// firmware/assets/generated/ next to ui_assets.h. Re-export it whenever a template changes.
//
// Format 1 (stable; later versions only add fields):
//   The screen is a fixed 128x160. A template is a list of zones; each zone is an absolute
//   rectangle in screen pixels (x, y, w, h), drawn in list order (later = on top). Nothing stretches.
//   p[] holds the role's parameters, unused entries are 0:
//     UI_ZONE_LIST      p[0] row height, p[1] icon size, p[2] icon x, p[3] icon y (inside a row),
//                       p[4] label x (inside the zone), p[5] scrollbar width. Visible rows = h / row height.
//     UI_ZONE_DETAIL    p[0] row height, p[1] value column x (inside the zone). Rows = h / row height.
//     UI_ZONE_TEXT      p[0] inner padding
//     UI_ZONE_CAROUSEL  p[0] width of the selection box (centered, inset 2 px top and bottom)
//     UI_ZONE_STATUS    the status bar; a template without one is full-screen
//     UI_ZONE_ICON / UI_ZONE_IMAGE  fixed slots;  UI_ZONE_FREE  guide only
//
// Centering rule: when centering leaves an odd pixel (an odd-width item in an even-width space, or the
// other way round), the item goes toward the left / top: pos = start + floor((span - size) / 2).
// The Studio's snapping uses the same rule; uiCenterIn() below implements it.
#pragma once

#include <Arduino.h>
#include <string.h>

enum UiZoneRole : uint8_t {
  UI_ZONE_FREE = 0,
  UI_ZONE_STATUS = 1,
  UI_ZONE_TEXT = 2,
  UI_ZONE_LIST = 3,
  UI_ZONE_ICON = 4,
  UI_ZONE_IMAGE = 5,
  UI_ZONE_DETAIL = 6,
  UI_ZONE_CAROUSEL = 7
};

struct UiZone {
  const char* name;
  uint8_t role;              // UiZoneRole
  int16_t x, y, w, h;
  int16_t p[6];              // role parameters, see above
};

struct UiTemplate {
  const char* id;            // the Studio's template id (a mockup's meta.template)
  const char* name;
  const UiZone* zones;
  uint8_t zoneCount;
};

constexpr uint8_t UI_TEMPLATE_FORMAT = 1;

// start + floor((span - size) / 2): an odd leftover pixel goes to the right / bottom, so the item sits left / up
inline int16_t uiCenterIn(int16_t start, int16_t span, int16_t size) {
  const int16_t d = span - size;
  return start + (d >= 0 ? d / 2 : -((1 - d) / 2));
}
inline int16_t uiZoneRows(const UiZone& z) { return z.p[0] > 0 ? z.h / z.p[0] : 0; }

