constexpr uint8_t UI_TEMPLATE_COUNT = 13;

inline const UiTemplate* uiFindTemplate(const char* id) {
  for (uint8_t i = 0; i < UI_TEMPLATE_COUNT; i++) if (strcmp(UI_TEMPLATES[i].id, id) == 0) return &UI_TEMPLATES[i];
  return nullptr;
}
